import React from 'react';

export interface CatalogoUIProps {
  items: { id: string; nome: string; descricao: string; preco: number; imagem?: string }[];
  onSelect?: (id: string) => void;
  onAddToCart?: (id: string) => void;
}

export function CatalogoUI({ items, onSelect, onAddToCart }: CatalogoUIProps) {
  if (!items || items.length === 0) {
    return React.createElement('div', { className: 'text-center p-8 text-gray-500' }, 'Nenhum item no catálogo');
  }

  const cards = items.map((item) => {
    return React.createElement('div', { key: item.id, className: 'border rounded-lg overflow-hidden hover:shadow-lg transition-shadow' },
      React.createElement('div', { className: 'h-48 bg-gray-200 flex items-center justify-center' },
        item.imagem 
          ? React.createElement('img', { src: item.imagem, alt: item.nome, className: 'w-full h-full object-cover' })
          : React.createElement('span', { className: 'text-gray-400' }, '??')
      ),
      React.createElement('div', { className: 'p-4' },
        React.createElement('h3', { className: 'font-semibold text-lg' }, item.nome),
        React.createElement('p', { className: 'text-gray-600 text-sm mb-2' }, item.descricao),
        React.createElement('p', { className: 'text-xl font-bold text-blue-600' }, 'R$ ' + item.preco.toFixed(2)),
        React.createElement('div', { className: 'flex gap-2 mt-3' },
          onSelect && React.createElement('button', { onClick: () => onSelect(item.id), className: 'flex-1 bg-blue-500 text-white py-1 rounded hover:bg-blue-600 text-sm transition-colors' }, 'Ver'),
          onAddToCart && React.createElement('button', { onClick: () => onAddToCart(item.id), className: 'flex-1 bg-green-500 text-white py-1 rounded hover:bg-green-600 text-sm transition-colors' }, 'Adicionar')
        )
      )
    );
  });

  return React.createElement('div', { className: 'grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4 p-4' }, cards);
}

import React from 'react';

export interface DashboardUIProps {
  title?: string;
  children: React.ReactNode;
  stats?: {
    label: string;
    value: number | string;
    icon?: React.ReactNode;
    color?: string;
  }[];
  actions?: {
    label: string;
    onClick: () => void;
    variant?: 'primary' | 'secondary' | 'success' | 'danger' | 'warning';
  }[];
}

export function DashboardUI({ 
  title = 'Dashboard', 
  children, 
  stats = [], 
  actions = [] 
}: DashboardUIProps) {
  const getButtonClass = (variant?: string): string => {
    const baseClass = 'px-4 py-2 rounded-lg text-white font-medium transition-colors';
    switch (variant) {
      case 'primary': return baseClass + ' bg-blue-500 hover:bg-blue-600';
      case 'secondary': return baseClass + ' bg-gray-500 hover:bg-gray-600';
      case 'success': return baseClass + ' bg-green-500 hover:bg-green-600';
      case 'danger': return baseClass + ' bg-red-500 hover:bg-red-600';
      case 'warning': return baseClass + ' bg-yellow-500 hover:bg-yellow-600';
      default: return baseClass + ' bg-blue-500 hover:bg-blue-600';
    }
  };

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">{title}</h1>
        <div className="flex gap-2">
          {actions.map((action, index) => (
            <button key={index} onClick={action.onClick} className={getButtonClass(action.variant)}>
              {action.label}
            </button>
          ))}
        </div>
      </div>

      {stats.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          {stats.map((stat, index) => (
            <div key={index} className="bg-white p-4 rounded-lg shadow border border-gray-100">
              <div className="flex items-center justify-between">
                <span className="text-gray-500 text-sm">{stat.label}</span>
                {stat.icon && <span className="text-2xl">{stat.icon}</span>}
              </div>
              <div className="text-2xl font-bold text-gray-800">{stat.value}</div>
            </div>
          ))}
        </div>
      )}

      <div className="bg-white rounded-lg shadow border border-gray-100 p-6">{children}</div>
    </div>
  );
}
import React from 'react';

export interface DemandViewProps {
  demands: { id: string; title: string; description: string; status: string }[];
  onSelect?: (id: string) => void;
}

export function DemandView({ demands, onSelect }: DemandViewProps) {
  if (!demands || demands.length === 0) {
    return React.createElement('div', { className: 'text-center p-8 text-gray-500' }, 'Nenhuma demanda encontrada');
  }

  const items = demands.map((demand) => {
    return React.createElement('div', { key: demand.id, onClick: () => onSelect && onSelect(demand.id), className: 'bg-white p-4 rounded-lg shadow border border-gray-100 hover:shadow-md transition-shadow cursor-pointer' },
      React.createElement('h3', { className: 'font-semibold text-lg' }, demand.title),
      React.createElement('p', { className: 'text-gray-600 text-sm' }, demand.description),
      React.createElement('span', { className: 'inline-block mt-2 px-2 py-1 text-xs font-semibold rounded-full bg-blue-100 text-blue-800' }, demand.status)
    );
  });

  return React.createElement('div', { className: 'space-y-4' }, items);
}
