export interface PratoListProps {
  pratos: Prato[];
  onEdit?: (id: string) => void;
  onDelete?: (id: string) => void;
  onView?: (id: string) => void;
  loading?: boolean;
}

interface Prato {
  id: string;
  nome: string;
  descricao: string;
  preco: number;
  categoria: string;
  status: 'ativo' | 'inativo';
}

export function PratoList({ pratos, onEdit, onDelete, onView, loading = false }: PratoListProps) {
  if (loading) {
    return React.createElement('div', { className: 'flex justify-center items-center p-8' },
      React.createElement('div', { className: 'animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500' })
    );
  }

  if (!pratos || pratos.length === 0) {
    return React.createElement('div', { className: 'text-center p-8 text-gray-500' }, 'Nenhum prato cadastrado');
  }

  const rows = pratos.map((prato) => {
    const statusClass = prato.status === 'ativo' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800';
    const statusText = prato.status === 'ativo' ? 'Ativo' : 'Inativo';

    return React.createElement('tr', { key: prato.id, className: 'hover:bg-gray-50' },
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap' },
        React.createElement('div', { className: 'text-sm font-medium text-gray-900' }, prato.nome),
        React.createElement('div', { className: 'text-sm text-gray-500' }, prato.descricao)
      ),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap text-sm text-gray-500' }, prato.categoria),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap text-sm text-gray-900' }, 'R$ ' + prato.preco.toFixed(2)),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap' },
        React.createElement('span', { className: 'px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full ' + statusClass }, statusText)
      ),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap text-sm font-medium' },
        React.createElement('div', { className: 'flex gap-2' },
          onView && React.createElement('button', { onClick: () => onView(prato.id), className: 'text-blue-600 hover:text-blue-900 transition-colors' }, 'Ver'),
          onEdit && React.createElement('button', { onClick: () => onEdit(prato.id), className: 'text-green-600 hover:text-green-900 transition-colors' }, 'Editar'),
          onDelete && React.createElement('button', { onClick: () => onDelete(prato.id), className: 'text-red-600 hover:text-red-900 transition-colors' }, 'Deletar')
        )
      )
    );
  });

  return React.createElement('div', { className: 'overflow-x-auto' },
    React.createElement('table', { className: 'min-w-full divide-y divide-gray-200' },
      React.createElement('thead', { className: 'bg-gray-50' },
        React.createElement('tr', {},
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Nome'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Categoria'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Preço'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Status'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Ações')
        )
      ),
      React.createElement('tbody', { className: 'bg-white divide-y divide-gray-200' }, rows)
    )
  );
}
