import React from 'react';

export interface DashboardUIProps {
  title?: string;
  children: React.ReactNode;
  stats?: {
    label: string;
    value: number | string;
    icon?: React.ReactNode;
    color?: string;
  }[];
  actions?: {
    label: string;
    onClick: () => void;
    variant?: 'primary' | 'secondary' | 'success' | 'danger' | 'warning';
  }[];
}

export function DashboardUI({ 
  title = 'Dashboard', 
  children, 
  stats = [], 
  actions = [] 
}: DashboardUIProps) {
  const getButtonClass = (variant?: string): string => {
    const baseClass = 'px-4 py-2 rounded-lg text-white font-medium transition-colors';
    switch (variant) {
      case 'primary': return baseClass + ' bg-blue-500 hover:bg-blue-600';
      case 'secondary': return baseClass + ' bg-gray-500 hover:bg-gray-600';
      case 'success': return baseClass + ' bg-green-500 hover:bg-green-600';
      case 'danger': return baseClass + ' bg-red-500 hover:bg-red-600';
      case 'warning': return baseClass + ' bg-yellow-500 hover:bg-yellow-600';
      default: return baseClass + ' bg-blue-500 hover:bg-blue-600';
    }
  };

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">{title}</h1>
        <div className="flex gap-2">
          {actions.map((action, index) => (
            <button key={index} onClick={action.onClick} className={getButtonClass(action.variant)}>
              {action.label}
            </button>
          ))}
        </div>
      </div>

      {stats.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          {stats.map((stat, index) => (
            <div key={index} className="bg-white p-4 rounded-lg shadow border border-gray-100">
              <div className="flex items-center justify-between">
                <span className="text-gray-500 text-sm">{stat.label}</span>
                {stat.icon && <span className="text-2xl">{stat.icon}</span>}
              </div>
              <div className="text-2xl font-bold text-gray-800">{stat.value}</div>
            </div>
          ))}
        </div>
      )}

      <div className="bg-white rounded-lg shadow border border-gray-100 p-6">{children}</div>
    </div>
  );
}
