export interface ModalRevendedorProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (data: any) => void;
}

export function ModalRevendedor({ isOpen, onClose, onConfirm }: ModalRevendedorProps) {
  const [formData, setFormData] = React.useState({
    nome: '',
    cnpj: '',
    email: '',
    telefone: '',
    endereco: ''
  });

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onConfirm(formData);
    onClose();
  };

  const handleChange = (field: string, value: string) => {
    setFormData({ ...formData, [field]: value });
  };

  return React.createElement('div', { className: 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50' },
    React.createElement('div', { className: 'bg-white rounded-lg p-6 max-w-md w-full' },
      React.createElement('div', { className: 'flex justify-between items-center mb-4' },
        React.createElement('h2', { className: 'text-2xl font-bold' }, 'Cadastrar Revendedor'),
        React.createElement('button', { onClick: onClose, className: 'text-gray-500 hover:text-gray-700 transition-colors' }, '?')
      ),
      React.createElement('form', { onSubmit: handleSubmit, className: 'space-y-4' },
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Nome'),
          React.createElement('input', { type: 'text', value: formData.nome, onChange: (e) => handleChange('nome', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2', required: true })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'CNPJ'),
          React.createElement('input', { type: 'text', value: formData.cnpj, onChange: (e) => handleChange('cnpj', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2' })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Email'),
          React.createElement('input', { type: 'email', value: formData.email, onChange: (e) => handleChange('email', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2', required: true })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Telefone'),
          React.createElement('input', { type: 'tel', value: formData.telefone, onChange: (e) => handleChange('telefone', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2' })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Endereço'),
          React.createElement('input', { type: 'text', value: formData.endereco, onChange: (e) => handleChange('endereco', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2' })
        ),
        React.createElement('button', { type: 'submit', className: 'w-full bg-blue-500 text-white py-2 rounded-lg hover:bg-blue-600 transition-colors' }, 'Cadastrar')
      )
    )
  );
}
