export interface ModalAssinaturaProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  planos: { id: string; nome: string; preco: number; recursos: string[] }[];
}

export function ModalAssinatura({ isOpen, onClose, onConfirm, planos }: ModalAssinaturaProps) {
  if (!isOpen) return null;

  const planoElements = planos.map((plano) => {
    const recursosList = plano.recursos.map((recurso, idx) => 
      React.createElement('li', { key: idx, className: 'flex items-center gap-2' },
        React.createElement('span', { className: 'text-green-500' }, '?'),
        recurso
      )
    );

    return React.createElement('div', { key: plano.id, className: 'border rounded-lg p-4 hover:shadow-lg transition-shadow' },
      React.createElement('h3', { className: 'font-bold text-lg' }, plano.nome),
      React.createElement('p', { className: 'text-2xl font-bold text-blue-600 my-2' }, 'R$ ' + plano.preco.toFixed(2)),
      React.createElement('ul', { className: 'text-sm space-y-1' }, recursosList),
      React.createElement('button', { onClick: () => { onConfirm(); onClose(); }, className: 'w-full mt-4 bg-blue-500 text-white py-2 rounded-lg hover:bg-blue-600 transition-colors' }, 'Assinar')
    );
  });

  return React.createElement('div', { className: 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50' },
    React.createElement('div', { className: 'bg-white rounded-lg p-6 max-w-2xl w-full max-h-[80vh] overflow-y-auto' },
      React.createElement('div', { className: 'flex justify-between items-center mb-4' },
        React.createElement('h2', { className: 'text-2xl font-bold' }, 'Escolha seu Plano'),
        React.createElement('button', { onClick: onClose, className: 'text-gray-500 hover:text-gray-700 transition-colors' }, '?')
      ),
      React.createElement('div', { className: 'grid grid-cols-1 md:grid-cols-3 gap-4' }, planoElements)
    )
  );
}
import React from 'react';

export interface ModalRevendedorProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (data: any) => void;
}

export function ModalRevendedor({ isOpen, onClose, onConfirm }: ModalRevendedorProps) {
  const [formData, setFormData] = React.useState({
    nome: '',
    cnpj: '',
    email: '',
    telefone: '',
    endereco: ''
  });

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onConfirm(formData);
    onClose();
  };

  const handleChange = (field: string, value: string) => {
    setFormData({ ...formData, [field]: value });
  };

  return React.createElement('div', { className: 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50' },
    React.createElement('div', { className: 'bg-white rounded-lg p-6 max-w-md w-full' },
      React.createElement('div', { className: 'flex justify-between items-center mb-4' },
        React.createElement('h2', { className: 'text-2xl font-bold' }, 'Cadastrar Revendedor'),
        React.createElement('button', { onClick: onClose, className: 'text-gray-500 hover:text-gray-700 transition-colors' }, '?')
      ),
      React.createElement('form', { onSubmit: handleSubmit, className: 'space-y-4' },
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Nome'),
          React.createElement('input', { type: 'text', value: formData.nome, onChange: (e) => handleChange('nome', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2', required: true })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'CNPJ'),
          React.createElement('input', { type: 'text', value: formData.cnpj, onChange: (e) => handleChange('cnpj', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2' })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Email'),
          React.createElement('input', { type: 'email', value: formData.email, onChange: (e) => handleChange('email', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2', required: true })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Telefone'),
          React.createElement('input', { type: 'tel', value: formData.telefone, onChange: (e) => handleChange('telefone', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2' })
        ),
        React.createElement('div', {},
          React.createElement('label', { className: 'block text-sm font-medium text-gray-700' }, 'Endereço'),
          React.createElement('input', { type: 'text', value: formData.endereco, onChange: (e) => handleChange('endereco', e.target.value), className: 'mt-1 block w-full border border-gray-300 rounded-md p-2' })
        ),
        React.createElement('button', { type: 'submit', className: 'w-full bg-blue-500 text-white py-2 rounded-lg hover:bg-blue-600 transition-colors' }, 'Cadastrar')
      )
    )
  );
}
import React from 'react';

export interface PratoListProps {
  pratos: Prato[];
  onEdit?: (id: string) => void;
  onDelete?: (id: string) => void;
  onView?: (id: string) => void;
  loading?: boolean;
}

interface Prato {
  id: string;
  nome: string;
  descricao: string;
  preco: number;
  categoria: string;
  status: 'ativo' | 'inativo';
}

export function PratoList({ pratos, onEdit, onDelete, onView, loading = false }: PratoListProps) {
  if (loading) {
    return React.createElement('div', { className: 'flex justify-center items-center p-8' },
      React.createElement('div', { className: 'animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500' })
    );
  }

  if (!pratos || pratos.length === 0) {
    return React.createElement('div', { className: 'text-center p-8 text-gray-500' }, 'Nenhum prato cadastrado');
  }

  const rows = pratos.map((prato) => {
    const statusClass = prato.status === 'ativo' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800';
    const statusText = prato.status === 'ativo' ? 'Ativo' : 'Inativo';

    return React.createElement('tr', { key: prato.id, className: 'hover:bg-gray-50' },
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap' },
        React.createElement('div', { className: 'text-sm font-medium text-gray-900' }, prato.nome),
        React.createElement('div', { className: 'text-sm text-gray-500' }, prato.descricao)
      ),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap text-sm text-gray-500' }, prato.categoria),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap text-sm text-gray-900' }, 'R$ ' + prato.preco.toFixed(2)),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap' },
        React.createElement('span', { className: 'px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full ' + statusClass }, statusText)
      ),
      React.createElement('td', { className: 'px-6 py-4 whitespace-nowrap text-sm font-medium' },
        React.createElement('div', { className: 'flex gap-2' },
          onView && React.createElement('button', { onClick: () => onView(prato.id), className: 'text-blue-600 hover:text-blue-900 transition-colors' }, 'Ver'),
          onEdit && React.createElement('button', { onClick: () => onEdit(prato.id), className: 'text-green-600 hover:text-green-900 transition-colors' }, 'Editar'),
          onDelete && React.createElement('button', { onClick: () => onDelete(prato.id), className: 'text-red-600 hover:text-red-900 transition-colors' }, 'Deletar')
        )
      )
    );
  });

  return React.createElement('div', { className: 'overflow-x-auto' },
    React.createElement('table', { className: 'min-w-full divide-y divide-gray-200' },
      React.createElement('thead', { className: 'bg-gray-50' },
        React.createElement('tr', {},
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Nome'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Categoria'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Preço'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Status'),
          React.createElement('th', { className: 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider' }, 'Ações')
        )
      ),
      React.createElement('tbody', { className: 'bg-white divide-y divide-gray-200' }, rows)
    )
  );
}
import React from 'react';

export interface SelecaoPerfilUIProps {
  perfis: { id: string; nome: string; descricao: string }[];
  onSelect: (id: string) => void;
  selected?: string;
}

export function SelecaoPerfilUI({ perfis, onSelect, selected }: SelecaoPerfilUIProps) {
  if (!perfis || perfis.length === 0) {
    return React.createElement('div', { className: 'text-center p-8 text-gray-500' }, 'Nenhum perfil disponível');
  }

  const cards = perfis.map((perfil) => {
    const isSelected = selected === perfil.id;
    const className = isSelected 
      ? 'p-4 border rounded-lg cursor-pointer transition-all border-blue-500 bg-blue-50 shadow-md'
      : 'p-4 border rounded-lg cursor-pointer transition-all border-gray-200 hover:border-blue-300 hover:shadow';
    
    return React.createElement('div', { key: perfil.id, onClick: () => onSelect(perfil.id), className: className },
      React.createElement('h3', { className: 'font-semibold text-lg' }, perfil.nome),
      React.createElement('p', { className: 'text-gray-600 text-sm' }, perfil.descricao)
    );
  });

  return React.createElement('div', { className: 'grid grid-cols-1 md:grid-cols-3 gap-4 p-4' }, cards);
}


